/* =====================================================================
   PICTURE KANA (and more picture kanji): drawings built on the character's own strokes.
   Each stroke is drawn as part of an object (a fishhook, an eel, a road…), with a few extra
   shapes around it, so the character is hidden inside the picture. All drawn for this app.
   Strokes: KanjiVG (CC BY-SA 3.0), 109×109 coordinates.
   ===================================================================== */
const KA = { ink: '#3B3127', skin: '#F2C9A5', red: '#E25B4F', blue: '#4A7FC1', jeans: '#4A5A8C', bark: '#8B5A2B', wood: '#B98A5A', leaf: '#7DBB6A', leaf2: '#5FA052', water: '#4A90D9', sky: '#DCEEFB', sun: '#F6C744', fire: '#F28C28', gold: '#E8B923', metal: '#8A97A6', grey: '#7C8188', pink: '#F29A9A', white: '#FFFFFF', cream: '#F4E3B5', purple: '#8E6CC0', orange: '#F28C28', green: '#3FA34D', black: '#2B2B3A', brown: '#7A5A35', yellow: '#F7D54A', sand: '#EAD7A8', stone: '#A9A39A' };
const kaC = (cx, cy, r, f, ol = 1) => `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${f}"${ol ? ` stroke="${KA.ink}" stroke-width="1.8"` : ''}/>`;
const kaE = (cx, cy, rx, ry, f, ol = 1, rot = 0) => `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${f}"${ol ? ` stroke="${KA.ink}" stroke-width="1.8"` : ''}${rot ? ` transform="rotate(${rot} ${cx} ${cy})"` : ''}/>`;
const kaP = (d, f = 'none', ol = 1, w = 1.8) => `<path d="${d}" fill="${f}"${ol ? ` stroke="${KA.ink}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"` : ''}/>`;
const kaL = (d, col, w = 3) => `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const kaR = (x, y, w, h, f, rx = 0, ol = 0) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${f}"${ol ? ` stroke="${KA.ink}" stroke-width="1.8"` : ''}/>`;
const kaEye = (x, y, r = 2.2) => kaC(x, y, r, KA.white, 1) + kaC(x + r * .25, y, r * .5, KA.ink, 0);
const kaLeaf = (x, y, a = 0, s = 1) => `<path d="M0 0 C 4 -6, 12 -6, 16 0 C 12 6, 4 6, 0 0 Z" fill="${KA.leaf}" stroke="${KA.ink}" stroke-width="1.4" transform="translate(${x} ${y}) rotate(${a}) scale(${s})"/>`;
const kaDrop = (x, y, s = 1, f = KA.water) => `<path d="M0 -6 C 3 -1, 4 2, 0 5 C -4 2, -3 -1, 0 -6 Z" fill="${f}" stroke="${KA.ink}" stroke-width="1" transform="translate(${x} ${y}) scale(${s})"/>`;
const kaSky = (h = 109, f = KA.sky) => kaR(4, 4, 101, h - 8, f, 12);
const kaSea = (y, f = '#BFE0F6') => `<path d="M4 ${y} Q 20 ${y - 4} 36 ${y} T 68 ${y} T 105 ${y} V105 H4 Z" fill="${f}"/>`;
const kaGround = (y, f = '#C9A97A') => `<path d="M4 ${y} H105 V105 H4 Z" fill="${f}"/>`;
const kaSmile = (x, y, w = 6) => kaL(`M${x - w} ${y} Q ${x} ${y + w * .8} ${x + w} ${y}`, KA.ink, 1.6);
/* stroke styles: [colour, width]. A stroke is drawn with a dark outline so it reads as an object. */
