/** picture → picture with the strokes over it → the character, all from the stroke data */
function kaArt(ch, paths, fade) {
  const a = KANA_ART[ch]; if (!a || !paths) return '';
  const st = a.s || (a.p || []).flatMap(([n, c, w]) => Array(n).fill([c, w]));   // p: runs of strokes sharing a colour
  const strokes = paths.map((d, i) => { const [c, w] = st[i] || [KA.ink, 5]; return `<path d="${d}" fill="none" stroke="${KA.ink}" stroke-width="${w + 2.6}" stroke-linecap="round" stroke-linejoin="round"/><path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`; }).join('');
  return `${a.b ? a.b() : ''}${strokes}${a.f ? a.f() : ''}`;
}
function kaStrip(ch, paths) {
  const a = KANA_ART[ch]; if (!a || !paths) return '';
  const bg = `<rect x="0" y="0" width="109" height="109" rx="13" fill="#FBF7EE"/>`, art = kaArt(ch, paths);
  const glyph = col => paths.map(d => `<path d="${d}" fill="none" stroke="${col}" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>`).join('');
  const svg = (inner, lab) => `<svg viewBox="0 0 109 109" role="img" aria-label="${esc(lab)}">${bg}${inner}</svg>`;
  const cap = esc(a.c).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
  return `<div class="kps kas" data-kps="${esc(ch)}">
    <div class="kps-row"><figure>${svg(art, a.c.replace(/\*/g, ''))}</figure><span class="kps-a">→</span>
      <figure class="kps-mid">${svg(`<g class="kps-art">${art}</g><g class="kps-g">${glyph('#C0392B')}</g>`, 'The character traced over the picture')}</figure><span class="kps-a">→</span>
      <figure>${svg(glyph(KA.ink), ch)}</figure></div>
    <div class="kps-cap"><span>${a.r ? '' : '<b class="kps-tag">Memory picture</b> '}${cap}</span><button class="ghost kps-play" onclick="App.kpPlay(this)">▶ Watch it change</button></div>
  </div>`;
}

/** the picture strip for any character that has one: hand-drawn kanji, or a stroke-built picture */
const hasArt = ch => !!(KPIC[ch] || (KANA_ART[ch] && KART_PATHS[ch]));
const artStrip = ch => KPIC[ch] ? kpStrip(ch) : kaStrip(ch, KART_PATHS[ch]);
/** kana with ゛ or ゜ (が, パ) share the picture of their plain form */
function kanaArt(ch) {
  if (KANA_ART[ch] && KART_PATHS[ch]) return kaStrip(ch, KART_PATHS[ch]);
  const base = ch.normalize('NFD')[0], mark = ch.normalize('NFD')[1];
  if (base !== ch && KANA_ART[base] && KART_PATHS[base]) return `<p class="kas-note">${esc(ch)} is ${esc(base)} with ${mark === '゙' ? 'two little dashes (゛), which make the sound voiced' : 'a little circle (゜), which makes it a p-sound'}. Remember ${esc(base)}:</p>` + kaStrip(base, KART_PATHS[base]);
  return '';
}

